#include <set>
#include <iostream>

int main() {
    std::multiset<int> ms = {10, 30, 50};

    // 1. Basic insertion: Returns iterator to the new element
    auto it1 = ms.insert(30); 
    std::cout << "New element inserted: " << *it1 << "\n";

    // 2. Optimized insertion using a position hint
    // We know 40 comes after 30 (it1 points to one 30)
    // Using the hint makes this insertion O(1) if the hint is good.
    auto it2 = ms.insert(it1, 40); 
    std::cout << "Optimized insertion at: " << *it2 << "\n";

    // 3. Bad hint (forces O(log N) search)
    // ms.begin() is a poor hint for inserting 100
    ms.insert(ms.begin(), 100);
}
